import{_ as e,o as t,c as a,Q as s}from"./chunks/framework.b67c47e6.js";const m=JSON.parse('{"title":"Setting Up IFC Parsing","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/ifcps/index.md","filePath":"tutorials/ifcps/index.md","lastUpdated":1790250076000}'),r={name:"tutorials/ifcps/index.md"},o=s('<h1 id="setting-up-ifc-parsing" tabindex="-1">Setting Up IFC Parsing <a class="header-anchor" href="#setting-up-ifc-parsing" aria-label="Permalink to &quot;Setting Up IFC Parsing&quot;">​</a></h1><p>This tutorial walks you through building an IFC Parsing Setup (IFC PS) from nothing, in the order that works: get the file split into panels first, then name the parts, then tune what the machines and the measurements make of them.</p><nav class="table-of-contents"><ul><li><a href="#prerequisites">Prerequisites</a></li><li><a href="#what-is-an-ifc-parsing-setup">What is an IFC Parsing Setup?</a></li><li><a href="#the-short-route-have-claude-draft-it">The short route: have Claude draft it</a></li><li><a href="#step-1-create-the-setup">Step 1: Create the setup</a></li><li><a href="#step-2-hierarchy-and-project">Step 2: Hierarchy and project</a></li><li><a href="#step-3-panel-part-categories">Step 3: Panel part categories</a></li><li><a href="#step-4-custom-part-branches">Step 4: Custom part branches</a></li><li><a href="#step-5-part-properties">Step 5: Part properties</a></li><li><a href="#step-6-custom-part-classes">Step 6: Custom part classes</a></li><li><a href="#step-7-operations-and-machines">Step 7: Operations and machines</a></li><li><a href="#step-8-steel-cage-part-categories">Step 8: Steel cage part categories</a></li><li><a href="#step-9-test-it-on-a-real-file">Step 9: Test it on a real file</a></li><li><a href="#step-10-assign-it-to-your-projects">Step 10: Assign it to your projects</a></li><li><a href="#next-steps">Next Steps</a></li></ul></nav><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>You must have <strong>manager</strong> or <strong>admin</strong> access.</li><li>Have a sample IFC file ready to test your configuration.</li></ul><h2 id="what-is-an-ifc-parsing-setup" tabindex="-1">What is an IFC Parsing Setup? <a class="header-anchor" href="#what-is-an-ifc-parsing-setup" aria-label="Permalink to &quot;What is an IFC Parsing Setup?&quot;">​</a></h2><p>The IFC standard is open, and every BIM application exports it its own way. What one exporter calls <code>REFERENCE</code> another writes into a property set, and a stud is recognised by its name in one file and by its profile in the next. A parsing setup is how you tell produuz.it to read <strong>your</strong> files.</p><p>A company can have several setups, and each project uses one.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This tutorial is the path through it. For what every single field does, see the <a href="/guide/management/ifcps/">IFC Parsing Setup guide</a>.</p></div><h2 id="the-short-route-have-claude-draft-it" tabindex="-1">The short route: have Claude draft it <a class="header-anchor" href="#the-short-route-have-claude-draft-it" aria-label="Permalink to &quot;The short route: have Claude draft it&quot;">​</a></h2><p>Before you start clicking, know that you do not have to fill every tab by hand. With the <a href="/guide/mcp/">Claude connector</a> added, you can hand Claude the property list of a few elements from your BIM application, describe your panels in your own words, and ask it for a setup file. You upload it, and the rest of this tutorial becomes checking rather than typing.</p><p>That is worth doing even when you intend to build the setup yourself: a draft tells you which properties your exporter actually writes and which tabs you will have to think about.</p><p>See: <a href="/guide/management/ifcps/json/">The setup file (JSON)</a></p><p>The steps below are the full path, and they are the same steps you walk to check a draft.</p><h2 id="step-1-create-the-setup" tabindex="-1">Step 1: Create the setup <a class="header-anchor" href="#step-1-create-the-setup" aria-label="Permalink to &quot;Step 1: Create the setup&quot;">​</a></h2><ol><li>Go to <strong>Company settings → IFC Parsing Setups</strong>.</li><li>Click <strong>New</strong>, or clone an existing setup if one is already close to what you need. <strong>UPLOAD</strong> brings in a setup file if you already have one.</li><li>Give it a descriptive name, such as <code>Cadwork Standard</code> or <code>Tekla Wall Panels</code>. Names are capped at 22 characters.</li></ol><p>The editor opens on seven tabs. The filter box at the top left of each tab searches the settings by name <strong>and</strong> by the values inside their rules, so typing <code>STIJL</code> lands on every rule that uses it.</p><p>Every setting has an <strong>(i)</strong> button that opens the help panel on the right. Leave it open while you work; it follows whatever you pressed last.</p><div class="tip custom-block"><p class="custom-block-title">Look at your file first</p><p>Open your sample IFC in your BIM application or an IFC viewer and look at one stud, one plate and one panel. Write down which property carries the name, the reference and the layer. Nearly every rule you are about to write comes from that list.</p></div><h2 id="step-2-hierarchy-and-project" tabindex="-1">Step 2: Hierarchy and project <a class="header-anchor" href="#step-2-hierarchy-and-project" aria-label="Permalink to &quot;Step 2: Hierarchy and project&quot;">​</a></h2><p>Nothing else works until the file is split correctly, so start here.</p><ul><li><strong>Levels detection</strong> — which IFC class or property groups elements into a module, a panel and a subassembly.</li><li><strong>Unit and project properties</strong> — what is read off each module and panel once it has been recognised: its name, its unit id, and the phase and batch it belongs to, plus any extra values of yours that should travel with it.</li><li><strong>Assembly filter</strong> — which assemblies are produced at all. A project file usually holds more than your factory makes: foundations, in-situ concrete, a neighbouring building. Leave both lists empty and everything is split.</li></ul><h2 id="step-3-panel-part-categories" tabindex="-1">Step 3: Panel part categories <a class="header-anchor" href="#step-3-panel-part-categories" aria-label="Permalink to &quot;Step 3: Panel part categories&quot;">​</a></h2><p>A <strong>category</strong> says what a part is: a top rail, a stud, a plate, a brick, an opening. This is the tab that turns elements into parts.</p><p>Each category holds <strong>rules</strong>, and a part matches the category when <strong>any one</strong> of its rules matches. A rule is three fields: the IFC property to look into, the type of match (<em>full word</em>, <em>prefix</em> or <em>contains</em>), and the value.</p><div class="tip custom-block"><p class="custom-block-title">Example</p><p>Two rules on <em>Top Rail Wood</em>:</p><table><thead><tr><th>IFC Prop</th><th>Type of match</th><th>Value</th></tr></thead><tbody><tr><td>REFERENCE</td><td>Match full word</td><td>TOPRAIL</td></tr><tr><td>REFERENCE</td><td>Match prefix</td><td>TR</td></tr></tbody></table><p><code>TOPRAIL</code>, <code>TR</code>, <code>TR12</code> and <code>TR45</code> are top rails. <code>TOPRAIL2</code> and <code>TOP_RAIL</code> are not.</p></div><p>Start with the frame and the plates. Bricks, openings and the areas can wait until the basics come out right.</p><h2 id="step-4-custom-part-branches" tabindex="-1">Step 4: Custom part branches <a class="header-anchor" href="#step-4-custom-part-branches" aria-label="Permalink to &quot;Step 4: Custom part branches&quot;">​</a></h2><p>Branches are kinds of part beyond the built-in timber and plate: windows, connectors, airtightness, electrical, plumbing.</p><p>Each branch has a name, its own rules, the geometry it <strong>resembles</strong> — wood-like, plate-like or generic — and two switches: whether its parts go through <strong>logistics</strong>, and whether they <strong>count in the panel measurements</strong>.</p><p>That second one matters more than it looks. A branch is recognised before a part falls back to timber or plate from its category, so a part your setup knows perfectly well can end up with no category — and a part with no category is outside the panel width, height, thickness and surface. Turn it on for cladding and window frames; leave it off for brackets that stick out past the frame.</p><p>Those measurements also draw your <strong>rack loads</strong>, so getting them wrong is not only a wrong number in a report.</p><p>Skip this tab if everything in your panels is timber and sheet material.</p><h2 id="step-5-part-properties" tabindex="-1">Step 5: Part properties <a class="header-anchor" href="#step-5-part-properties" aria-label="Permalink to &quot;Step 5: Part properties&quot;">​</a></h2><p>Categories say what a part is; properties say where each of its values is read from. Name, reference, material, finish, comment, weight, volume, and the zone or layer the part belongs to.</p><p>Leave a property empty and produuz.it falls back to its default source, which for the name is the element&#39;s own Name attribute.</p><h2 id="step-6-custom-part-classes" tabindex="-1">Step 6: Custom part classes <a class="header-anchor" href="#step-6-custom-part-classes" aria-label="Permalink to &quot;Step 6: Custom part classes&quot;">​</a></h2><p>A category says what a part <strong>is</strong>. A class says how your factory treats it.</p><p>Classes are entirely your own: nothing is built in, and a part is an I-beam only because a rule you wrote says so. Give each class a name and the rules that recognise it. A part gets the <strong>first class in the list whose rules match</strong>, so put the more specific ones first.</p><p>A class does two things.</p><p><strong>Its name</strong> is what settings that behave differently per kind of part look up, the framing nail matrix of the machine setups first of all.</p><p><strong>Its behaviours</strong> say what the class does to the four panel measurements — width, height, thickness and surface. Press <strong>Behaviours</strong> on the class row. Everything is off by default, and off means the part counts, so a class with no behaviours changes nothing.</p><div class="info custom-block"><p class="custom-block-title">The case this was built for</p><p>Some modellers add a layer to a panel that is not produced but occupies the space a real one will take: an insulation layer, a finish, a service cavity.</p><p>It has to count for the <strong>thickness</strong>, because the panel really is that thick. It must not count for the <strong>surface</strong>, because nothing was produced.</p><p>Give it a class, turn on <em>Ignore in surface</em>, <em>Ignore in width</em> and <em>Ignore in height</em>, and leave <em>Ignore in thickness</em> <strong>off</strong>.</p></div><p>See: <a href="/guide/management/ifcps/#custom-part-classes">Custom part classes</a></p><h2 id="step-7-operations-and-machines" tabindex="-1">Step 7: Operations and machines <a class="header-anchor" href="#step-7-operations-and-machines" aria-label="Permalink to &quot;Step 7: Operations and machines&quot;">​</a></h2><p>Nail lines, saw cuts, drills, milling and glue are modelled as elements too. The rules here tell them apart from parts, and the properties below them — nail spacing, mill depth, tool ID — feed the machine files directly.</p><p>Operations never count towards the width, height, thickness or surface of a panel, so a saw mark that hangs below the bottom rail does not make the panel taller.</p><h2 id="step-8-steel-cage-part-categories" tabindex="-1">Step 8: Steel cage part categories <a class="header-anchor" href="#step-8-steel-cage-part-categories" aria-label="Permalink to &quot;Step 8: Steel cage part categories&quot;">​</a></h2><p>Only if you produce steel cages. It is a secondary flow with its own rails, profiles, plates and welding seams. Leave it empty otherwise.</p><h2 id="step-9-test-it-on-a-real-file" tabindex="-1">Step 9: Test it on a real file <a class="header-anchor" href="#step-9-test-it-on-a-real-file" aria-label="Permalink to &quot;Step 9: Test it on a real file&quot;">​</a></h2><ol><li>Open a project and upload your sample IFC.</li><li>Split the file and generate the designs.</li><li>Open one in the viewer and check: <ul><li>parts land in the right categories, and nothing lands in <strong>unknown</strong>;</li><li>the names, references and materials read correctly;</li><li>the panel width, height and thickness match the model;</li><li>hidden and ignored elements behave as you meant them to.</li></ul></li></ol><p>Parts showing up as <em>unknown</em> means no rule recognised them. Find one in the model, look at its properties, and add the rule that catches it.</p><div class="info custom-block"><p class="custom-block-title">Saving relaunches the analysis</p><p>Saving a setup that projects are using relaunches their analysis, so every panel is re-read with the new rules. The editor lists the affected projects before it does, and offers to save the setup as a clone instead.</p><p>If your company has <em>Launch analysis automatically</em> turned off, nothing is relaunched and the designs keep their old numbers until you launch the analysis yourself.</p></div><h2 id="step-10-assign-it-to-your-projects" tabindex="-1">Step 10: Assign it to your projects <a class="header-anchor" href="#step-10-assign-it-to-your-projects" aria-label="Permalink to &quot;Step 10: Assign it to your projects&quot;">​</a></h2><ol><li>Open a project&#39;s settings.</li><li>Select your setup as its parsing setup.</li><li>Every file processed in that project from now on uses it.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Create one setup per BIM application or project type rather than one setup with rules for all of them. They are cheap to clone and far easier to debug.</p></div><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/guide/management/ifcps/json/">The setup file (JSON)</a> — the format behind the Download and Upload buttons, and how to have Claude write one.</li><li><a href="/tutorials/projects/">Build a Project</a> — upload files and generate designs using your setup.</li><li><a href="/tutorials/production_lines/">Production Lines Setup</a> — configure your production workflow.</li></ul>',58),i=[o];function n(l,h,p,c,d,u){return t(),a("div",null,i)}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
